<style>
.rr-workspace{max-width:1440px;margin:auto;padding:28px 24px;color:#172d40;overflow-wrap:anywhere}.rr-heading,.rr-card-heading,.rr-results-heading,.rr-card footer{display:flex;align-items:flex-start;justify-content:space-between;gap:16px}.rr-heading h1{font-size:30px;font-weight:750;letter-spacing:-.03em}.rr-heading p,.rr-note,.rr-card-heading p,.rr-results-heading span,.rr-card time{color:#596b7c;font-size:14px}.rr-note{margin:16px 0}.rr-filters,.rr-card,.rr-notice{border:1px solid #dce5ec;background:#fff;border-radius:14px;padding:20px;box-shadow:0 2px 6px #18344b05}.rr-filters{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:16px;margin:22px 0}.rr-filters label{font-size:13px;font-weight:650;min-width:0}.rr-filters input,.rr-filters select{display:block;width:100%;min-width:0;min-height:44px;border:1px solid #b8c7d3;border-radius:8px;padding:9px 11px;background:#fff;margin-top:6px;font-size:14px}.rr-filter-actions{display:flex;align-items:center;gap:18px;grid-column:1/-1}.rr-filter-actions a{font-size:14px;text-decoration:underline;padding:10px 0}.rr-results-heading{align-items:center;margin-bottom:14px}.rr-results-heading h2,.rr-card h2{font-size:18px;font-weight:700}.rr-list{display:grid;gap:14px}.rr-card-heading h2{margin-top:5px}.rr-facts{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:20px;margin:22px 0}.rr-facts dt{font-size:12px;color:#637487;margin-bottom:5px}.rr-facts dd{font-size:16px;font-weight:650;margin:0}.rr-early{display:inline-block;font-size:12px;font-weight:650;color:#884409;background:#fff3dc;border-radius:6px;padding:4px 8px;margin-top:6px}.rr-card footer{border-top:1px solid #e6edf2;padding-top:15px;align-items:center}.rr-card footer p{font-size:13px;color:#526779}.rr-empty{padding:36px;text-align:center}.rr-empty p{margin:10px 0 20px}.rr-pagination{margin-top:22px}.rr-notice{margin:20px 0;background:#f0f8f6}.rr-workspace :is(a,button,input,select,textarea,summary):focus-visible{outline:3px solid #167bba;outline-offset:3px}.rr-detail{max-width:1180px}.rr-detail>article,.rr-detail>section{border-radius:14px}.rr-detail .rr-current{border-left:4px solid #197eb6;background:#f0f7fc;padding:18px;border-radius:10px;margin-top:20px}.rr-detail .rr-current h2{font-weight:700}.rr-detail .rr-next{display:flex;gap:12px;flex-wrap:wrap;margin-top:14px}.rr-detail :is(input,textarea){max-width:100%;min-width:0}.rr-detail details>summary{cursor:pointer;min-height:44px;font-weight:700;padding:10px 0}.rr-detail .rr-timeline{border-left:2px solid #d7e5ef;padding-left:16px}
@media(max-width:900px){.rr-filters{grid-template-columns:repeat(2,minmax(0,1fr))}.rr-facts{gap:14px}}@media(max-width:600px){.rr-workspace{padding:20px 12px}.rr-heading,.rr-card-heading,.rr-card footer{flex-direction:column}.rr-heading h1{font-size:26px}.rr-filters,.rr-facts{grid-template-columns:1fr}.rr-card,.rr-filters{padding:16px}.rr-card footer a{width:100%;text-align:center}.rr-results-heading{align-items:flex-start;flex-direction:column;gap:3px}.rr-detail .rr-next>*{width:100%}}
</style>
